def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    # panels are separated by full 0 columns; panel width = H (square panels)
    pw = H
    starts = list(range(0, W, pw + 1))
    n = len(starts)

    def key(mask):
        return tuple(map(tuple, mask.astype(int)))

    # legend read off the train pairs: hole pattern -> row colour
    def m(cells):
        a = np.zeros((4, 4), int)
        for y, x in cells:
            a[y, x] = 1
        return tuple(map(tuple, a))
    table = {
        m([]): 2,
        m([(1, 1), (1, 2), (2, 1), (2, 2)]): 8,
        m([(2, 1), (2, 2), (3, 1), (3, 2)]): 4,
        m([(1, 0), (2, 0), (1, 3), (2, 3)]): 3,
    }

    out = np.zeros((n, 3), int)
    emit(out.copy(), "Allocate a canvas with one 3-wide row per 4x4 panel of the input.")
    for i, x0 in enumerate(starts):
        panel = g[:, x0:x0 + pw]
        c = table.get(key(panel == 0), 0)
        out[i, :] = c
        emit(out.copy(), f"Panel {i+1}'s hole pattern stands for colour {c}; fill output row {i} with it.")
    return out
